def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def parse_amount(token: str):
        if token.isascii() and token.isdigit():
            return int(token)
        return None

    for idx, op in enumerate(ops):
        parts = op.split(" ")
        if any(not p for p in parts):
            rejected.append(idx)
            continue

        verb = parts[0]
        n_parts = len(parts)

        if verb == "open" and n_parts == 3:
            acc = parts[1]
            amt = parse_amount(parts[2])
            if amt is not None and acc not in balances:
                balances[acc] = amt
                history.append(("open", acc))
            else:
                rejected.append(idx)

        elif verb == "deposit" and n_parts == 3:
            acc = parts[1]
            amt = parse_amount(parts[2])
            if amt is not None and amt > 0 and acc in balances:
                balances[acc] += amt
                history.append(("deposit", acc, amt))
            else:
                rejected.append(idx)

        elif verb == "withdraw" and n_parts == 3:
            acc = parts[1]
            amt = parse_amount(parts[2])
            if (
                amt is not None
                and amt > 0
                and acc in balances
                and acc not in frozen
                and balances[acc] >= amt
            ):
                balances[acc] -= amt
                history.append(("withdraw", acc, amt))
            else:
                rejected.append(idx)

        elif verb == "transfer" and n_parts == 4:
            src, dst = parts[1], parts[2]
            amt = parse_amount(parts[3])
            if (
                amt is not None
                and amt > 0
                and src != dst
                and src in balances
                and dst in balances
                and src not in frozen
                and balances[src] >= amt
            ):
                balances[src] -= amt
                balances[dst] += amt
                history.append(("transfer", src, dst, amt))
            else:
                rejected.append(idx)

        elif verb == "freeze" and n_parts == 2:
            acc = parts[1]
            if acc in balances and acc not in frozen:
                frozen.add(acc)
                history.append(("freeze", acc))
            else:
                rejected.append(idx)

        elif verb == "unfreeze" and n_parts == 2:
            acc = parts[1]
            if acc in balances and acc in frozen:
                frozen.remove(acc)
                history.append(("unfreeze", acc))
            else:
                rejected.append(idx)

        elif verb == "undo" and n_parts == 1:
            if not history:
                rejected.append(idx)
                continue
            entry = history.pop()
            kind = entry[0]
            if kind == "open":
                del balances[entry[1]]
            elif kind == "deposit":
                balances[entry[1]] -= entry[2]
            elif kind == "withdraw":
                balances[entry[1]] += entry[2]
            elif kind == "transfer":
                balances[entry[1]] += entry[3]
                balances[entry[2]] -= entry[3]
            elif kind == "freeze":
                frozen.remove(entry[1])
            elif kind == "unfreeze":
                frozen.add(entry[1])

        else:
            rejected.append(idx)

    return balances, rejected
